import type { Metadata } from "next";
import Link from "next/link";
import { notFound, redirect } from "next/navigation";
import { updateVendorCompany } from "@/src/actions/vendor";
import { getCurrentUserProfile } from "@/src/lib/auth";
import { prisma } from "@/src/lib/prisma";
import { requireCompanyManager } from "@/src/lib/vendor";

export const dynamic = "force-dynamic";
export const metadata: Metadata = { title: "Edit Company Profile", robots: { index: false, follow: false } };
type Props = { params: Promise<{ slug: string }>; searchParams: Promise<{ saved?: string }> };
export default async function VendorCompanyPage({ params, searchParams }: Props) { const user = await getCurrentUserProfile(); if (!user) redirect("/sign-in?redirect_url=%2Fvendor"); const company = await prisma.company.findUnique({ where: { slug: (await params).slug } }); if (!company) notFound(); if (!(await requireCompanyManager(user.id, company.id))) redirect("/vendor"); const saved = (await searchParams).saved === "true"; return <main className="mx-auto max-w-3xl px-4 py-12"><Link href="/vendor" className="text-caption font-semibold text-accent">← Vendor Dashboard</Link><h1 className="mt-6 text-h1 text-text-primary">Edit {company.name}</h1><p className="mt-2 text-body text-text-secondary">Verified identifies your company representative. It does not endorse scientific or product claims.</p>{saved && <p className="mt-5 rounded-lg border border-border bg-bg-elevated p-3 text-body text-text-secondary">Company profile saved.</p>}<form action={updateVendorCompany} className="mt-8 grid gap-5"><input type="hidden" name="companyId" value={company.id} /><TextArea label="Description" name="description" value={company.description ?? ""} /><Field label="Short description" name="shortDescription" value={company.shortDescription ?? ""} /><Field label="Website" name="website" type="url" value={company.website ?? ""} required={false} /><Field label="Logo URL" name="logoUrl" type="url" value={company.logoUrl ?? ""} required={false} /><div className="grid gap-4 sm:grid-cols-2"><Field label="Country" name="country" value={company.country ?? ""} required={false} /><Field label="City" name="city" value={company.city ?? ""} required={false} /></div><label className="flex items-center gap-2 text-body text-text-secondary"><input type="checkbox" name="leadsEnabled" defaultChecked={company.leadsEnabled} />Allow verified users to request product demos</label><button className="w-fit rounded-md bg-text-primary px-4 py-2 text-caption font-semibold text-bg">Save company profile</button></form></main>; }
function Field({ label, name, value, type = "text", required = true }: { label: string; name: string; value: string; type?: string; required?: boolean }) { return <label className="grid gap-1 text-caption font-medium text-text-secondary">{label}<input name={name} type={type} required={required} defaultValue={value} className="rounded-md border border-border bg-bg px-3 py-2 text-body text-text-primary focus:border-accent focus:outline-none" /></label>; }
function TextArea({ label, name, value }: { label: string; name: string; value: string }) { return <label className="grid gap-1 text-caption font-medium text-text-secondary">{label}<textarea name={name} required minLength={20} rows={8} defaultValue={value} className="rounded-md border border-border bg-bg px-3 py-2 text-body text-text-primary focus:border-accent focus:outline-none" /></label>; }
